import re

def entities(doc, scope):
    scope_node = node_by_title(doc, scope)
    children_nodes = children(doc, scope_node)
    products_node = None
    for child in children_nodes:
        if child['kind'] == 'table' and 'Products' in child['title']:
            products_node = child
            break
    if products_node is None:
        return []
    rows = table_rows(products_node)
    result = []
    for _, row in rows:
        result.append({
            "id": row['product'],
            "description": f"{row['product']} ({row['group']}/{row['sub-group']}, storage {row['storage location']}, {row['kg per unit']} kg/unit)"
        })
    return result


def recorded_end(doc, scope):
    scope_node = node_by_title(doc, scope)
    children_nodes = children(doc, scope_node)
    ledger_node = None
    for child in children_nodes:
        if child['kind'] == 'table' and 'Daily ledger' in child['title']:
            ledger_node = child
            break
    if ledger_node:
        rows = table_rows(ledger_node)
        if rows:
            return max(float(row['day']) for _, row in rows)
    return None


def params(doc, scope):
    scope_node = node_by_title(doc, scope)
    children_nodes = children(doc, scope_node)
    result = {}
    for child in children_nodes:
        if child['kind'] == 'text':
            match = re.search(r'dispatch capacity:\s*(\d+)\s*kg', child['text'], re.IGNORECASE)
            if match:
                result['dispatch_capacity_kg'] = float(match.group(1))
    return result


def inputs(doc, scope):
    scope_node = node_by_title(doc, scope)
    children_nodes = children(doc, scope_node)
    products_node = None
    ledger_node = None
    order_book_table = None
    for child in children_nodes:
        if child['kind'] == 'table' and 'Products' in child['title']:
            products_node = child
        elif child['kind'] == 'table' and 'Daily ledger' in child['title']:
            ledger_node = child
        elif child['kind'] == 'table' and 'Order book' in child['title'] and 'Orders received' in child['title']:
            order_book_table = child
    result = []
    if products_node:
        prod_rows = table_rows(products_node)
        for idx, row in prod_rows:
            result.append({
                "id": f"opening_stock_{row['product']}",
                "time": None,
                "kind": "opening_stock",
                "entities": [row['product']],
                "fields": {
                    "opening_stock": int(row['opening stock']),
                    "kg_per_unit": float(row['kg per unit'])
                },
                "src": [[products_node['node_id'], idx, ['product', 'opening stock', 'kg per unit']]]
            })
    if ledger_node:
        ledger_rows = table_rows(ledger_node)
        for idx, row in ledger_rows:
            day = float(row['day'])
            product = row['product']
            result.append({
                "id": f"daily_{product}_{int(day)}",
                "time": day,
                "kind": "daily_input",
                "entities": [product],
                "fields": {"produced": int(row['produced']), "ordered": int(row['ordered'])},
                "src": [[ledger_node['node_id'], idx, ['produced', 'ordered', 'day', 'date', 'product']]]
            })
    if order_book_table:
        ob_rows = table_rows(order_book_table)
        for idx, row in ob_rows:
            day = float(row['day'])
            product = row['product']
            result.append({
                "id": f"future_{product}_{int(day)}",
                "time": day,
                "kind": "planned_input",
                "entities": [product],
                "fields": {"planned_production": int(row['planned production']), "ordered": int(row['ordered'])},
                "src": [[order_book_table['node_id'], idx, ['planned production', 'ordered', 'day', 'date', 'product']]]
            })
    return result


def _match_entities_in_line(line, entity_ids):
    result = []
    for eid in entity_ids:
        escaped = re.escape(eid)
        pattern = r'(?<![A-Za-z0-9\-])' + escaped + r'(?![A-Za-z0-9\-])'
        if re.search(pattern, line):
            result.append(eid)
    return result


def outcomes(doc, scope):
    scope_node = node_by_title(doc, scope)
    children_nodes = children(doc, scope_node)
    ledger_node = None
    events_node = None
    open_orders_node = None
    for child in children_nodes:
        if child['kind'] == 'table' and 'Daily ledger' in child['title']:
            ledger_node = child
        elif child['kind'] == 'list' and 'Events' in child['title']:
            events_node = child
        elif child['kind'] == 'table' and 'Open orders' in child['title']:
            open_orders_node = child
    entity_ids = [e['id'] for e in entities(doc, scope)]
    result = []
    if ledger_node:
        ledger_rows = table_rows(ledger_node)
        for idx, row in ledger_rows:
            day = float(row['day'])
            product = row['product']
            result.append({
                "time": day,
                "kind": "shipped",
                "entities": [product],
                "value": int(row['shipped']),
                "src": [[ledger_node['node_id'], idx, ['shipped', 'day', 'date', 'product']]]
            })
            result.append({
                "time": day,
                "kind": "backordered",
                "entities": [product],
                "value": int(row['backordered']),
                "src": [[ledger_node['node_id'], idx, ['backordered', 'day', 'date', 'product']]]
            })
            result.append({
                "time": day,
                "kind": "stock",
                "entities": [product],
                "value": int(row['stock']),
                "src": [[ledger_node['node_id'], idx, ['stock', 'day', 'date', 'product']]]
            })
    if events_node:
        lines = events_node.get('lines', [])
        for line_idx, line in enumerate(lines):
            match = re.match(r'Day\s+(\d+)', line)
            if match:
                day = float(match.group(1))
                entities_in_event = _match_entities_in_line(line, entity_ids)
                line_lower = line.lower()
                if 'dispatch capacity reached' in line_lower:
                    kind = "dispatch_capacity_reached"
                elif 'runs out of stock' in line_lower:
                    kind = "stock_out"
                elif 'fully backordered' in line_lower:
                    kind = "fully_backordered"
                elif 'backlog' in line_lower and 'cleared' in line_lower:
                    kind = "backlog_cleared"
                else:
                    kind = "event"
                result.append({
                    "time": day,
                    "kind": kind,
                    "entities": entities_in_event,
                    "value": None,
                    "src": [[events_node['node_id'], line_idx]]
                })
    if open_orders_node:
        oo_rows = table_rows(open_orders_node)
        end_day_match = re.search(r'end of day\s+(\d+)', open_orders_node['title'])
        end_day = float(end_day_match.group(1)) if end_day_match else None
        for idx, row in oo_rows:
            result.append({
                "time": end_day,
                "kind": "open_order",
                "entities": [row['product']],
                "value": int(row['units still open']),
                "src": [[open_orders_node['node_id'], idx, ['product', 'day placed', 'units still open']]]
            })
    return result


# ---- step 2: forward model ----
def simulate(doc, scope, inputs, params, start=None, horizon=None):
    import re
    from collections import defaultdict

    cap_kg = params.get('dispatch_capacity_kg')
    if cap_kg is None:
        try:
            scope_node = node_by_title(doc, scope)
            for child in children(doc, scope_node):
                if child['kind'] == 'text':
                    m = re.search(r'dispatch capacity:\s*(\d+)', child['text'], re.IGNORECASE)
                    if m:
                        cap_kg = float(m.group(1))
                        break
        except Exception:
            pass
    if cap_kg is None:
        cap_kg = 407700.0

    opening = {}
    daily_data = {}

    for inp in inputs:
        if inp['kind'] == 'opening_stock':
            opening[inp['entities'][0]] = inp['fields']
        elif inp['kind'] in ('daily_input', 'planned_input'):
            day = inp['time']
            prod = inp['entities'][0]
            if day not in daily_data:
                daily_data[day] = {}
            fields = inp['fields']
            daily_data[day][prod] = {
                'produced': fields.get('produced', fields.get('planned_production', 0)),
                'ordered': fields.get('ordered', 0)
            }

    if not opening:
        return []

    all_days = sorted(daily_data.keys())
    if not all_days:
        return []

    if horizon is None:
        horizon = all_days[-1]

    stock = {p: float(v['opening_stock']) for p, v in opening.items()}
    kg = {p: float(v['kg_per_unit']) for p, v in opening.items()}
    orders = []
    outcomes = []

    last_stock_out = {}
    prev_bo_pos = {p: False for p in opening}

    for day in all_days:
        if day > horizon:
            break

        cap_left = cap_kg
        day_shipped = defaultdict(float)
        day_inputs = daily_data.get(day, {})

        # 1. Production arrives
        for p, vals in day_inputs.items():
            stock[p] += vals['produced']

        # 2. Orders join the queue
        for p, vals in day_inputs.items():
            if vals['ordered'] > 0:
                orders.append({'p': p, 'day': day, 'rem': float(vals['ordered']), 'orig': float(vals['ordered'])})

        # 3. Dispatch
        # Oldest first; same day -> smaller remaining first, then lower product code
        orders.sort(key=lambda o: (o['day'], o['rem'], o['p']))

        cap_reached = False
        for o in orders:
            if cap_left <= 1e-9:
                break
            p = o['p']
            if p not in kg: 
                continue
            w = kg[p]

            can_cap = int(cap_left / w)
            can_stk = int(stock[p])
            can_rem = int(o['rem'])

            ship = min(can_cap, can_stk, can_rem)

            if ship > 0:
                o['rem'] -= ship
                stock[p] -= ship
                cap_left -= ship * w
                day_shipped[p] += ship

                if ship < can_stk and ship == can_cap:
                    cap_reached = True

        # Clean fulfilled orders
        orders = [o for o in orders if o['rem'] > 0.5]

        # 4. Records
        bo = defaultdict(float)
        for o in orders:
            bo[o['p']] += o['rem']

        for p in opening:
            sv = int(round(day_shipped[p]))
            bv = int(round(bo[p]))
            stok = int(round(stock[p]))

            outcomes.append({"time": float(day), "kind": "shipped", "entities": [p], "value": sv})
            outcomes.append({"time": float(day), "kind": "backordered", "entities": [p], "value": bv})
            outcomes.append({"time": float(day), "kind": "stock", "entities": [p], "value": stok})

            if cap_reached:
                outcomes.append({"time": float(day), "kind": "dispatch_capacity_reached", "entities": [], "value": None})

            if stok == 0 and bv > 0:
                if last_stock_out.get(p) != day - 1:
                    outcomes.append({"time": float(day), "kind": "stock_out", "entities": [p], "value": None})
                last_stock_out[p] = day
            else:
                last_stock_out[p] = None

            curr_bo_pos = bv > 0
            if prev_bo_pos[p] and not curr_bo_pos:
                outcomes.append({"time": float(day), "kind": "backlog_cleared", "entities": [p], "value": None})
            prev_bo_pos[p] = curr_bo_pos

        for o in orders:
            if o['day'] == day and abs(o['rem'] - o['orig']) < 0.5:
                outcomes.append({"time": float(day), "kind": "fully_backordered", "entities": [o['p']], "value": None})

    if start is not None:
        outcomes = [o for o in outcomes if o['time'] > start]

    return outcomes

